insert into public.recipe_steps(dish_id,step_number,body) select id,1,'Lava y licua culantro y espinaca con poca agua. Reserva en frío.' from public.dishes where slug='arroz-con-pollo';
insert into public.recipe_steps(dish_id,step_number,body) select id,2,'Corta el pollo; reserva huesos para hervir con apio 20–30 minutos. Cuela el caldo.' from public.dishes where slug='arroz-con-pollo';
insert into public.recipe_steps(dish_id,step_number,body) select id,3,'Salpimienta el pollo y séllalo en aceite 2 minutos por lado. Retira.' from public.dishes where slug='arroz-con-pollo';
insert into public.recipe_steps(dish_id,step_number,body) select id,4,'Sofríe cebolla 10 minutos, ajo 3 y pasta de ají amarillo 10, a fuego bajo.' from public.dishes where slug='arroz-con-pollo';
insert into public.recipe_steps(dish_id,step_number,body) select id,5,'Añade chicha, la mitad del licuado verde, caldo y pollo. Tapa y cocina 25 minutos, hasta cocerlo.' from public.dishes where slug='arroz-con-pollo';
insert into public.recipe_steps(dish_id,step_number,body) select id,6,'Retira el pollo y mide el caldo: por cada taza de arroz, usa una taza y una cucharada de caldo.' from public.dishes where slug='arroz-con-pollo';
insert into public.recipe_steps(dish_id,step_number,body) select id,7,'Añade arroz, zanahoria, arvejas y choclo al caldo. Sazona, tapa y cocina a fuego mínimo.' from public.dishes where slug='arroz-con-pollo';
insert into public.recipe_steps(dish_id,step_number,body) select id,8,'A los 5 minutos, incorpora el licuado restante y el pollo con sus jugos. Tapa 10 minutos más, hasta granear.' from public.dishes where slug='arroz-con-pollo';
insert into public.recipe_steps(dish_id,step_number,body) select id,9,'Licua el ají amarillo sin venas ni semillas con queso, leche y aceite para la huancaína. Sancocha las papas.' from public.dishes where slug='arroz-con-pollo';
insert into public.recipe_steps(dish_id,step_number,body) select id,10,'Asa el pimiento, retira piel y semillas y córtalo. Sirve arroz y pollo con pimiento y papas cubiertas de huancaína.' from public.dishes where slug='arroz-con-pollo';
