insert into public.recipe_steps(dish_id,step_number,body) select id,1,'Corta una punta de las caiguas y extrae las semillas. Hiérvelas con sal 2 minutos, enfría en agua helada y escurre.' from public.dishes where slug='caigua-rellena';
insert into public.recipe_steps(dish_id,step_number,body) select id,2,'Sofríe cebolla y ajo con aceite. Añade tomate, pasta de tomate y pastas de ají panca y amarillo; cocina el aderezo removiendo.' from public.dishes where slug='caigua-rellena';
insert into public.recipe_steps(dish_id,step_number,body) select id,3,'Incorpora la carne, sal, pimienta, comino y orégano. Cocina 10–15 minutos, hasta que esté hecha. Separa unas cucharadas de este guiso para la salsa.' from public.dishes where slug='caigua-rellena';
insert into public.recipe_steps(dish_id,step_number,body) select id,4,'Al relleno restante agrega pan remojado y escurrido, pasas, aceitunas sin pepa y huevo ya cocido y picado. Mezcla y retira del fuego.' from public.dishes where slug='caigua-rellena';
insert into public.recipe_steps(dish_id,step_number,body) select id,5,'Rellena las caiguas y ciérralas con las puntas. En una olla, une el guiso reservado con agua o caldo; coloca las caiguas encima.' from public.dishes where slug='caigua-rellena';
insert into public.recipe_steps(dish_id,step_number,body) select id,6,'Tapa y cocina aproximadamente 15 minutos. Sirve con arroz blanco preparado aparte.' from public.dishes where slug='caigua-rellena';
