insert into public.recipe_steps(dish_id,step_number,body) select id,1,'Lava la quinua 4–5 veces y cuela. Cocina con dos tazas de agua por taza de quinua: al hervir, tapa y baja al mínimo 20 minutos. Reserva.' from public.dishes where slug='guiso-de-quinua';
insert into public.recipe_steps(dish_id,step_number,body) select id,2,'Sofríe cebolla en aceite 5 minutos; añade ajo y cocina 5 minutos. Agrega pasta de ají amarillo y sofríe otros 5 minutos.' from public.dishes where slug='guiso-de-quinua';
insert into public.recipe_steps(dish_id,step_number,body) select id,3,'Añade una ramita de huacatay y dórala para aromatizar. Incorpora agua —dos tazas por taza de quinua seca— y lleva a hervor.' from public.dishes where slug='guiso-de-quinua';
insert into public.recipe_steps(dish_id,step_number,body) select id,4,'Agrega la quinua cocida e integra. Ajusta la textura con agua caliente si hace falta.' from public.dishes where slug='guiso-de-quinua';
insert into public.recipe_steps(dish_id,step_number,body) select id,5,'Añade leche evaporada y queso en cubos. Al volver a hervir, retira del fuego y sazona con orégano y sal.' from public.dishes where slug='guiso-de-quinua';
insert into public.recipe_steps(dish_id,step_number,body) select id,6,'Sirve con el arroz cocinado por separado.' from public.dishes where slug='guiso-de-quinua';
