insert into public.recipe_steps(dish_id,step_number,body) select id,1,'Limpia el choclo. Soasa la mitad de la cebolla y licúala junto a los granos; reserva.' from public.dishes where slug='pepian-de-choclo';
insert into public.recipe_steps(dish_id,step_number,body) select id,2,'Corta la pechuga en trozos, salpimiéntala y dórala con aceite en una olla; retira.' from public.dishes where slug='pepian-de-choclo';
insert into public.recipe_steps(dish_id,step_number,body) select id,3,'En esa olla, sofríe la cebolla restante con ajo, ají panca, ají amarillo y culantro hasta cocinar el aderezo.' from public.dishes where slug='pepian-de-choclo';
insert into public.recipe_steps(dish_id,step_number,body) select id,4,'Añade loche finamente picado y devuelve el pollo. Incorpora caldo de pollo poco a poco hasta cocinar la carne.' from public.dishes where slug='pepian-de-choclo';
insert into public.recipe_steps(dish_id,step_number,body) select id,5,'Agrega el licuado de choclo y cocina a fuego bajo removiendo continuamente, hasta cocer y espesar. Ajusta sal y textura con caldo si hace falta.' from public.dishes where slug='pepian-de-choclo';
insert into public.recipe_steps(dish_id,step_number,body) select id,6,'Sirve el pepián con arroz cocido aparte.' from public.dishes where slug='pepian-de-choclo';
