insert into public.recipe_steps(dish_id,step_number,body) select id,1,'Salpimienta las presas de pollo y dóralas por ambos lados en una olla con aceite. Retira y reserva fuera de la olla.' from public.dishes where slug='arroz-a-la-jardinera';
insert into public.recipe_steps(dish_id,step_number,body) select id,2,'En esa misma olla, sofríe cebolla picada hasta ablandarla; incorpora ajo y cocina brevemente. Añade zanahoria en cubos, arvejas y choclo desgranado.' from public.dishes where slug='arroz-a-la-jardinera';
insert into public.recipe_steps(dish_id,step_number,body) select id,3,'Devuelve el pollo y añade agua para terminar de cocinarlo tapado a fuego medio. Retira las presas cuando estén cocidas y reserva calientes.' from public.dishes where slug='arroz-a-la-jardinera';
insert into public.recipe_steps(dish_id,step_number,body) select id,4,'Añade el arroz lavado al caldo con las verduras. Comprueba la cantidad de líquido necesaria para granear ese arroz y ajusta la sal.' from public.dishes where slug='arroz-a-la-jardinera';
insert into public.recipe_steps(dish_id,step_number,body) select id,5,'Cuando hierva, tapa y cocina a fuego mínimo hasta que el arroz esté listo. Reposa unos minutos sin destapar.' from public.dishes where slug='arroz-a-la-jardinera';
insert into public.recipe_steps(dish_id,step_number,body) select id,6,'Sirve el arroz con verduras y una presa de pollo por porción. El pollo reservado no se adereza fuera de la olla.' from public.dishes where slug='arroz-a-la-jardinera';
