insert into public.recipe_steps(dish_id,step_number,body) select id,1,'Corta la panceta en trozos y salpimiéntala. Dórala por ambos lados en la olla arrocera con aceite; retira y reserva.' from public.dishes where slug='arroz-con-chancho';
insert into public.recipe_steps(dish_id,step_number,body) select id,2,'En esa olla, sofríe ají mirasol 5 minutos, luego cebolla picada otros 5. Añade ajo y cocina 3 minutos; incorpora tomate pelado en cubos y cocina 5 más.' from public.dishes where slug='arroz-con-chancho';
insert into public.recipe_steps(dish_id,step_number,body) select id,3,'Devuelve el cerdo y añade agua para cubrirlo. Tapa y cocina unos 30 minutos, hasta que esté tierno.' from public.dishes where slug='arroz-con-chancho';
