insert into public.recipe_steps(dish_id,step_number,body) select id,5,'Incorpora el arroz crudo y mezcla. Ajusta el líquido para granearlo; tapa y completa el ciclo de la arrocera.' from public.dishes where slug='arroz-con-chancho';
insert into public.recipe_steps(dish_id,step_number,body) select id,6,'Sirve el arroz con los trozos de cerdo. La sarsa criolla es un acompañamiento aparte.' from public.dishes where slug='arroz-con-chancho';
