insert into public.recipe_steps(dish_id,step_number,body) select id,1,'Carne: corta y salpimienta el asado. Añade apio, poro, ajo, zanahoria y cebolla cortados; vierte el vino y refrigera 2 horas.' from public.dishes where slug='asado-al-vino';
insert into public.recipe_steps(dish_id,step_number,body) select id,2,'Escurre y reserva el marinado con sus verduras. Enharina ligeramente la carne, sacude el exceso y dora ambos lados con aceite.' from public.dishes where slug='asado-al-vino';
insert into public.recipe_steps(dish_id,step_number,body) select id,3,'Reúne carne, verduras y vino del marinado en una olla. Añade tomillo opcional; tapa y cocina a fuego lento unas 2 horas, hasta ablandar.' from public.dishes where slug='asado-al-vino';
insert into public.recipe_steps(dish_id,step_number,body) select id,4,'Puré: cocina las papas al vapor hasta ablandar; comprueba desde los 10–15 minutos. Pela y prensa calientes.' from public.dishes where slug='asado-al-vino';
insert into public.recipe_steps(dish_id,step_number,body) select id,5,'Bate la papa con leche y casi toda la mantequilla a fuego bajo 5 minutos. Para un puré más fino, cuélalo.' from public.dishes where slug='asado-al-vino';
insert into public.recipe_steps(dish_id,step_number,body) select id,6,'Retira la carne y cuela el líquido. Reúnelos nuevamente, ajusta la sal y añade la mantequilla reservada.' from public.dishes where slug='asado-al-vino';
insert into public.recipe_steps(dish_id,step_number,body) select id,7,'Sirve la carne sobre el puré y báñala con la salsa de vino.' from public.dishes where slug='asado-al-vino';
