insert into public.recipe_steps(dish_id,step_number,body) select id,1,'Pela y corta las papas crudas en cubos. Corta zanahoria y pechuga en cubos; lava la hierbabuena.' from public.dishes where slug='cau-cau-de-pollo';
insert into public.recipe_steps(dish_id,step_number,body) select id,2,'En una olla con aceite, sofríe cebolla y ajo. Añade ají amarillo, comino, palillo y pimienta; cocina el aderezo.' from public.dishes where slug='cau-cau-de-pollo';
