insert into public.recipe_steps(dish_id,step_number,body) select id,1,'Corta la cebolla en gajos y el ají amarillo en tiras. Sancocha camotes y huevos por separado; pela y reserva.' from public.dishes where slug='escabeche-de-pescado';
