insert into public.recipe_steps(dish_id,step_number,body) select id,1,'Frejoles: remoja la noche anterior, lava y hierve cubiertos con agua 30 minutos. Cambia el agua, añade pellejo de cerdo y cocina 60–90 minutos, hasta ablandar.' from public.dishes where slug='frejoles-con-seco-de-res';
insert into public.recipe_steps(dish_id,step_number,body) select id,2,'Frejoles: sofríe parte de la cebolla y luego ajo, 5 minutos cada uno. Añade frejoles cocidos y su caldo; cocina 10 minutos, sazona con orégano, pimienta y sal. Reserva.' from public.dishes where slug='frejoles-con-seco-de-res';
insert into public.recipe_steps(dish_id,step_number,body) select id,3,'Seco: dora la carne por ambos lados en otra olla y retira.' from public.dishes where slug='frejoles-con-seco-de-res';
insert into public.recipe_steps(dish_id,step_number,body) select id,4,'Sofríe la cebolla y el ajo restantes. Incorpora ají amarillo, culantro licuado y vinagre, cocinando cada incorporación unos 5 minutos.' from public.dishes where slug='frejoles-con-seco-de-res';
insert into public.recipe_steps(dish_id,step_number,body) select id,5,'Regresa la carne, cubre con agua o caldo y cocina a fuego bajo unos 40 minutos, hasta que esté tierna. Ajusta sal y pimienta.' from public.dishes where slug='frejoles-con-seco-de-res';
insert into public.recipe_steps(dish_id,step_number,body) select id,6,'Sirve el seco junto a los frejoles y al arroz cocido aparte; no mezcles los tres en la olla.' from public.dishes where slug='frejoles-con-seco-de-res';
