insert into public.recipe_steps(dish_id,step_number,body) select id,1,'Cuece las papas hasta que estén tiernas. Pélalas y prénsalas calientes; deja enfriar.' from public.dishes where slug='papa-rellena-con-arroz';
insert into public.recipe_steps(dish_id,step_number,body) select id,2,'Corta la carne en cubitos, salpimiéntala y dórala a fuego alto por tandas. Reserva fuera de la sartén.' from public.dishes where slug='papa-rellena-con-arroz';
insert into public.recipe_steps(dish_id,step_number,body) select id,3,'En la misma sartén, sofríe cebolla a fuego mínimo 15 minutos. Añade comino y ajo; cocina 5 minutos. Incorpora panca y cocina 10 más, removiendo.' from public.dishes where slug='papa-rellena-con-arroz';
insert into public.recipe_steps(dish_id,step_number,body) select id,4,'Devuelve la carne al aderezo y termina su cocción; añade agua si se pega. Ajusta la sal, agrega ají amarillo picado y enfría.' from public.dishes where slug='papa-rellena-con-arroz';
insert into public.recipe_steps(dish_id,step_number,body) select id,5,'Mezcla la papa fría con sal, fécula de papa, azúcar y aceite. Amasa solo hasta unir: trabajarla demasiado vuelve la masa pegajosa.' from public.dishes where slug='papa-rellena-con-arroz';
insert into public.recipe_steps(dish_id,step_number,body) select id,6,'Con las manos aceitadas, aplana una porción de papa. Coloca relleno, huevo cocido y aceituna en el centro; cierra y forma una papa ovalada.' from public.dishes where slug='papa-rellena-con-arroz';
insert into public.recipe_steps(dish_id,step_number,body) select id,7,'Fríe en aceite abundante a fuego medio unos 2½ minutos por lado, volteando con cuidado. Escurre y sirve con lechuga, mayonesa y ají si los elegiste.' from public.dishes where slug='papa-rellena-con-arroz';
