insert into public.recipe_steps(dish_id,step_number,body) select id,1,'Retira la tapa, venas y semillas de los rocotos. Blanquéalos en agua hirviendo con vinagre y azúcar, cambiando el agua tres veces. Enfría en agua helada y escurre.' from public.dishes where slug='rocoto-relleno-con-pastel-de-papa';
insert into public.recipe_steps(dish_id,step_number,body) select id,2,'Para la base roja, sofríe cebolla y luego ajo hasta formar un aderezo. Añade ají panca y cocina hasta integrar; agrega comino y cocina dos minutos.' from public.dishes where slug='rocoto-relleno-con-pastel-de-papa';
insert into public.recipe_steps(dish_id,step_number,body) select id,3,'Añade carne molida, sella y aromatiza con orégano. Incorpora el fondo de res para mantener el relleno húmedo; cocina la carne completamente.' from public.dishes where slug='rocoto-relleno-con-pastel-de-papa';
insert into public.recipe_steps(dish_id,step_number,body) select id,4,'A fuego mínimo, incorpora pasas, aceitunas, maní y un huevo duro picado. Ajusta sal y pimienta.' from public.dishes where slug='rocoto-relleno-con-pastel-de-papa';
insert into public.recipe_steps(dish_id,step_number,body) select id,5,'Rellena los rocotos; cubre con queso paria y coloca sus tapas. Reserva para gratinar.' from public.dishes where slug='rocoto-relleno-con-pastel-de-papa';
insert into public.recipe_steps(dish_id,step_number,body) select id,6,'Para el pastel, enmantequilla un molde. Alterna capas de papa cruda cortada muy fina y queso cremoso rallado.' from public.dishes where slug='rocoto-relleno-con-pastel-de-papa';
insert into public.recipe_steps(dish_id,step_number,body) select id,7,'Licúa leche evaporada con los cuatro huevos restantes, sal, pimienta y nuez moscada. Vierte sobre el pastel y distribuye mantequilla en cubitos.' from public.dishes where slug='rocoto-relleno-con-pastel-de-papa';
insert into public.recipe_steps(dish_id,step_number,body) select id,8,'Hornea el pastel a 180 °C unos 45 minutos, hasta que la papa esté cocida y la mezcla cuajada.' from public.dishes where slug='rocoto-relleno-con-pastel-de-papa';
insert into public.recipe_steps(dish_id,step_number,body) select id,9,'Gratina los rocotos a 200 °C hasta fundir y dorar el queso. Sirve junto al pastel.' from public.dishes where slug='rocoto-relleno-con-pastel-de-papa';
