insert into public.recipe_steps(dish_id,step_number,body) select id,2,'Añade carne molida y cocina removiendo para separar los grumos, hasta que deje de estar cruda.' from public.dishes where slug='tallarines-a-la-bolonesa';
insert into public.recipe_steps(dish_id,step_number,body) select id,3,'Incorpora tomate picado, sal y pimienta. Cocina a fuego bajo hasta deshacer el tomate y formar una salsa; añade un poco de agua si se seca.' from public.dishes where slug='tallarines-a-la-bolonesa';
insert into public.recipe_steps(dish_id,step_number,body) select id,4,'En otra olla, sancocha los tallarines en agua con sal hasta que estén al dente. Escurre.' from public.dishes where slug='tallarines-a-la-bolonesa';
