insert into public.recipe_steps(dish_id,step_number,body) select id,1,'Sumerge la pechuga de pavo 2–4 horas en salmuera refrigerada: 100 g de sal por litro de agua. Después escúrrela.' from public.dishes where slug='pechuga-de-pavo-al-horno';
insert into public.recipe_steps(dish_id,step_number,body) select id,2,'Mezcla mantequilla blanda con hojas picadas de romero y tomillo, mostaza, sal y pimienta.' from public.dishes where slug='pechuga-de-pavo-al-horno';
insert into public.recipe_steps(dish_id,step_number,body) select id,3,'Coloca poro, apio, zanahoria, cebolla y ajo cortados en la fuente. Unta mantequilla sobre y bajo la piel del pavo; acomódalo encima y añade vino.' from public.dishes where slug='pechuga-de-pavo-al-horno';
insert into public.recipe_steps(dish_id,step_number,body) select id,4,'Cubre con aluminio y hornea a 180 °C unos 45 minutos. Destapa, baña con los jugos y termina a 220 °C durante 20–30 minutos, comprobando la cocción.' from public.dishes where slug='pechuga-de-pavo-al-horno';
insert into public.recipe_steps(dish_id,step_number,body) select id,5,'Retira el pavo y cuela los jugos de la bandeja. Redúcelos a fuego bajo; si necesitan espesar, añade chuño disuelto en agua poco a poco y deja hervir.' from public.dishes where slug='pechuga-de-pavo-al-horno';
insert into public.recipe_steps(dish_id,step_number,body) select id,6,'Corta la pechuga en rodajas y sírvela con la salsa de sus jugos.' from public.dishes where slug='pechuga-de-pavo-al-horno';
