insert into public.recipe_steps(dish_id,step_number,body) select id,1,'Sofríe cebolla picada hasta dorarla; agrega ajo y cocina a fuego bajo. Incorpora la pasta de ají amarillo y cocina hasta integrar el aderezo. Aromatiza con orégano, sal y pimienta.' from public.dishes where slug='locro-de-zapallo';
insert into public.recipe_steps(dish_id,step_number,body) select id,2,'Añade zapallo en cubos y caldo de carne; tapa y cocina a fuego bajo hasta ablandar el zapallo, controlando el líquido.' from public.dishes where slug='locro-de-zapallo';
insert into public.recipe_steps(dish_id,step_number,body) select id,3,'Sancocha por separado papa en cubos, choclo y arvejas. Escurre y desgrana el choclo.' from public.dishes where slug='locro-de-zapallo';
insert into public.recipe_steps(dish_id,step_number,body) select id,4,'Agrega leche y queso en cubos al zapallo cocido; cocina un minuto. Mezcla con papa, choclo y arvejas.' from public.dishes where slug='locro-de-zapallo';
insert into public.recipe_steps(dish_id,step_number,body) select id,5,'Termina con huacatay picado. Sirve con arroz blanco cocido por separado.' from public.dishes where slug='locro-de-zapallo';
