insert into public.recipe_steps(dish_id,step_number,body) select id,1,'Pollo frito: abre las piernas a lo largo del hueso. Sumérgelas en leche mezclada con orégano, ajo, mostaza, sal y pimienta; refrigera toda la noche.' from public.dishes where slug='mostrito';
insert into public.recipe_steps(dish_id,step_number,body) select id,2,'Mezcla harina, chuño, páprika, pimienta y sal. Cubre las piernas escurridas con este empanizado y retira el exceso.' from public.dishes where slug='mostrito';
insert into public.recipe_steps(dish_id,step_number,body) select id,3,'Fríelas en aceite a 180 °C aproximadamente 10 minutos, verificando que estén cocidas junto al hueso. Escurre.' from public.dishes where slug='mostrito';
insert into public.recipe_steps(dish_id,step_number,body) select id,4,'Chaufa: dora la pechuga en trozos con sal a fuego alto hasta cocinarla; reserva.' from public.dishes where slug='mostrito';
insert into public.recipe_steps(dish_id,step_number,body) select id,5,'En otra sartén caliente, sofríe kion un minuto. Incorpora huevos batidos y rómpelos mientras cuajan.' from public.dishes where slug='mostrito';
insert into public.recipe_steps(dish_id,step_number,body) select id,6,'Agrega arroz cocido y frío; saltea a fuego alto soltando los granos. Devuelve la pechuga y agrega sillao, cebolla china, azúcar, sal y aceite de ajonjolí.' from public.dishes where slug='mostrito';
insert into public.recipe_steps(dish_id,step_number,body) select id,7,'Fríe las papas cortadas en bastones a 180 °C unos 6 minutos, hasta dorarlas. Escurre.' from public.dishes where slug='mostrito';
insert into public.recipe_steps(dish_id,step_number,body) select id,8,'Prepara una crema con mayonesa, limón, sal, pimienta y orégano. Sirve el chaufa junto a las piernas fritas, las papas y la crema.' from public.dishes where slug='mostrito';
