insert into public.recipe_steps(dish_id,step_number,body) select id,1,'Remoja el mote toda la noche con doble agua. Hiérvelo hasta cocinar; escurre y licúa con poca agua de cocción, espeso.' from public.dishes where slug='tamales-de-chancho';
insert into public.recipe_steps(dish_id,step_number,body) select id,2,'Retira nervaduras de las hojas; corta piezas de 30 × 40 cm y limpia con paño húmedo.' from public.dishes where slug='tamales-de-chancho';
insert into public.recipe_steps(dish_id,step_number,body) select id,3,'Hierve panceta cubierta de agua y mitad del ajo 30 minutos. Corta; reserva carne y caldo separados.' from public.dishes where slug='tamales-de-chancho';
insert into public.recipe_steps(dish_id,step_number,body) select id,4,'Dora pellejos con aceite hasta soltar grasa. Cubre con ese caldo, cocina 30 minutos y retíralos; reserva caldo.' from public.dishes where slug='tamales-de-chancho';
insert into public.recipe_steps(dish_id,step_number,body) select id,5,'Derrite manteca con sazonador de panca. Sofríe cebolla 8 minutos, ajo restante 3 y pastas de ají 5.' from public.dishes where slug='tamales-de-chancho';
insert into public.recipe_steps(dish_id,step_number,body) select id,6,'Añade mote, 1/4 taza del caldo, sal y pimienta. Remueve a fuego bajo 10 minutos: masa compacta, sin grumos.' from public.dishes where slug='tamales-de-chancho';
insert into public.recipe_steps(dish_id,step_number,body) select id,7,'Sobre dos hojas coloca masa, panceta, huevo, aceituna y ají; cubre con masa. Envuelve y ata.' from public.dishes where slug='tamales-de-chancho';
insert into public.recipe_steps(dish_id,step_number,body) select id,8,'Ponlos verticales sobre hojas y una rejilla, sin sumergir. Tapa; cocina al vapor 90 minutos a fuego bajo, reponiendo agua.' from public.dishes where slug='tamales-de-chancho';
