insert into public.recipe_steps(dish_id,step_number,body) select id,1,'Marinado: mezcla ají panca, vinagre, cerveza negra, comino, ajo, sal, pimienta, orégano, ají amarillo en tiras y cebolla en gajos. Incorpora el hígado limpio y refrigera 4–8 horas.' from public.dishes where slug='higado-encebollado-con-pure';
insert into public.recipe_steps(dish_id,step_number,body) select id,2,'Puré: pela y corta las papas en cuartos. Cocínalas tapadas con agua y sal a fuego bajo unos 20 minutos, hasta que estén tiernas.' from public.dishes where slug='higado-encebollado-con-pure';
insert into public.recipe_steps(dish_id,step_number,body) select id,3,'Agrega leche a las papas, aplasta y bate hasta formar el puré. Incorpora mantequilla y mantenlo caliente.' from public.dishes where slug='higado-encebollado-con-pure';
insert into public.recipe_steps(dish_id,step_number,body) select id,4,'Escurre y reserva el marinado. Fríe el hígado con aceite a fuego medio 2 minutos por lado. Añade cebolla y ají del marinado; cocina un minuto más, hasta completar la cocción.' from public.dishes where slug='higado-encebollado-con-pure';
