insert into public.recipe_steps(dish_id,step_number,body) select id,1,'Hierve el mondongo con agua, hierbabuena y leche unos 90 minutos, hasta ablandarlo. Reserva parte del caldo, limpia la membrana y corta el mondongo en tiras.' from public.dishes where slug='mondonguito-a-la-italiana';
