insert into public.recipe_steps(dish_id,step_number,body) select id,1,'Salpimienta el pollo y dóralo por ambos lados en una olla con aceite. Retíralo temporalmente.' from public.dishes where slug='pollo-a-la-gaseosa-negra';
insert into public.recipe_steps(dish_id,step_number,body) select id,2,'Sofríe la cebolla blanca picada en esa olla 12 minutos. Incorpora ajo y cocina 3 minutos; añade pasta de tomate y cocina otros 3.' from public.dishes where slug='pollo-a-la-gaseosa-negra';
insert into public.recipe_steps(dish_id,step_number,body) select id,3,'Vierte la gaseosa negra, devuelve las presas y cocina unos 20 minutos, hasta que el pollo esté cocido. Ajusta la sal.' from public.dishes where slug='pollo-a-la-gaseosa-negra';
insert into public.recipe_steps(dish_id,step_number,body) select id,4,'Añade pimiento en tiras. Disuelve chuño en agua fría y agrégalo poco a poco hasta espesar la salsa; hierve unos 3 minutos.' from public.dishes where slug='pollo-a-la-gaseosa-negra';
insert into public.recipe_steps(dish_id,step_number,body) select id,5,'Sancocha la papa aparte, córtala en rodajas y dórala en una sartén unos 3 minutos por lado. Sirve junto al pollo y su salsa.' from public.dishes where slug='pollo-a-la-gaseosa-negra';
