insert into public.recipe_steps(dish_id,step_number,body) select id,1,'Remoja los garbanzos previamente y escúrrelos. En una olla sofríe cebolla picada con aceite para formar el aderezo.' from public.dishes where slug='sopa-de-garbanzos-con-carne';
