insert into public.recipe_steps(dish_id,step_number,body) select id,1,'Sancocha parcialmente las papas en cuartos con agua y sal unos 5 minutos; escúrrelas y enfría.' from public.dishes where slug='salchipapa-con-todas-las-cremas';
insert into public.recipe_steps(dish_id,step_number,body) select id,2,'Corta hot dog y chorizo en rodajas. Dora la salchicha huachana en sartén; fríe hot dog y chorizo por separado unos 3 minutos y escurre.' from public.dishes where slug='salchipapa-con-todas-las-cremas';
insert into public.recipe_steps(dish_id,step_number,body) select id,3,'Fríe las papas hasta dorarlas. Escurre, sala y sirve con los embutidos y huevo frito.' from public.dishes where slug='salchipapa-con-todas-las-cremas';
insert into public.recipe_steps(dish_id,step_number,body) select id,4,'Mayonesa de leche: licúa leche fría, ajo, mostaza, limón, sal y pimienta; incorpora el aceite en hilo hasta emulsionar. Refrigera.' from public.dishes where slug='salchipapa-con-todas-las-cremas';
insert into public.recipe_steps(dish_id,step_number,body) select id,5,'Crema de aceituna: licúa parte de esa mayonesa con aceitunas sin pepa y orégano.' from public.dishes where slug='salchipapa-con-todas-las-cremas';
insert into public.recipe_steps(dish_id,step_number,body) select id,6,'Golf: mezcla mayonesa y kétchup. Spicy: mezcla otra porción con sriracha, sillao y aceite de ajonjolí.' from public.dishes where slug='salchipapa-con-todas-las-cremas';
insert into public.recipe_steps(dish_id,step_number,body) select id,7,'Ají de pollería: hierve ají amarillo desvenado 15 minutos, enfría y pela. Licúa con ajo, mostaza, orégano, huacatay, leche evaporada y aceite; emulsiona añadiendo aceite en hilo.' from public.dishes where slug='salchipapa-con-todas-las-cremas';
insert into public.recipe_steps(dish_id,step_number,body) select id,8,'Tártara: mezcla mayonesa con huevo cocido rallado, ajo, cebolla china y mostaza. Mantén las cremas refrigeradas hasta servir.' from public.dishes where slug='salchipapa-con-todas-las-cremas';
