insert into public.recipe_steps(dish_id,step_number,body) select id,1,'Corta zapallo en láminas, zanahoria en tiras, apio en rodajas y pechuga sin piel en cubos.' from public.dishes where slug='sopa-de-pollo';
insert into public.recipe_steps(dish_id,step_number,body) select id,2,'Hierve huesos y patas de pollo en agua unos 20 minutos. Cuela el caldo y retira los huesos.' from public.dishes where slug='sopa-de-pollo';
insert into public.recipe_steps(dish_id,step_number,body) select id,3,'Devuelve las patas al caldo junto a mollejas, pescuezos, apio, zanahoria, zapallo, ajo y kion. Cocina tapado a fuego medio 10 minutos.' from public.dishes where slug='sopa-de-pollo';
insert into public.recipe_steps(dish_id,step_number,body) select id,4,'Añade la pechuga y sal; hierve otros 10 minutos. Incorpora papa en cuartos y cocina unos 5 minutos, comprobando que esté tierna.' from public.dishes where slug='sopa-de-pollo';
insert into public.recipe_steps(dish_id,step_number,body) select id,5,'Agrega cabello de ángel y cocina aproximadamente 3 minutos, hasta que la pasta y el pollo estén listos.' from public.dishes where slug='sopa-de-pollo';
