insert into public.recipe_steps(dish_id,step_number,body) select id,1,'Sazona langostinos limpios, conchas y aros de calamar con sal, pimienta y sillao. Saltéalos por tandas a fuego alto unos 30 segundos y reserva.' from public.dishes where slug='chaufa-de-mariscos';
