insert into public.recipe_steps(dish_id,step_number,body) select id,1,'Mezcla sal, comino, romero, canela china, pimienta, ajo, cerveza negra y ají panca en polvo o pimentón.' from public.dishes where slug='pollo-a-la-brasa';
insert into public.recipe_steps(dish_id,step_number,body) select id,2,'Unta el pollo por dentro y fuera con ese adobo y refrigera toda la noche. Reserva parte del adobo para bañar después.' from public.dishes where slug='pollo-a-la-brasa';
insert into public.recipe_steps(dish_id,step_number,body) select id,3,'Hornea sobre aluminio a 200 °C 30 minutos. Mezcla cerveza y adobo reservado; baña el pollo y hornea 30 minutos más, bañando cada 10. Comprueba la cocción.' from public.dishes where slug='pollo-a-la-brasa';
insert into public.recipe_steps(dish_id,step_number,body) select id,4,'Mayonesa: licúa leche fría, ajo, mostaza, limón, sal y pimienta. Agrega aceite de girasol en hilo hasta emulsionar; refrigera.' from public.dishes where slug='pollo-a-la-brasa';
insert into public.recipe_steps(dish_id,step_number,body) select id,5,'Ají de pollería: desvena los ajíes amarillos y hiérvelos 15 minutos. Déjalos enfriar y pélalos.' from public.dishes where slug='pollo-a-la-brasa';
insert into public.recipe_steps(dish_id,step_number,body) select id,6,'Licúa esos ajíes con ajo, mostaza, orégano, sal, huacatay, leche evaporada y aceite. Añade más aceite en hilo hasta lograr una crema; refrigera.' from public.dishes where slug='pollo-a-la-brasa';
insert into public.recipe_steps(dish_id,step_number,body) select id,7,'Sirve el pollo con las cremas aparte. Los tiempos publicados corresponden a un pollo entero; verifica el punto si cambia el tamaño.' from public.dishes where slug='pollo-a-la-brasa';
