insert into public.recipe_steps(dish_id,step_number,body) select id,1,'Marina el pollo con sal, sillao, ajo, kion, ají limo, pimienta y aceite de ajonjolí durante 2 horas en refrigeración.' from public.dishes where slug='pollo-con-verduras-al-vapor';
insert into public.recipe_steps(dish_id,step_number,body) select id,2,'Corta la zanahoria y la cebolla china en bastones. En un recipiente resistente al calor, acomoda papas cóctel, pollo, brócoli y zanahoria; añade el marinado.' from public.dishes where slug='pollo-con-verduras-al-vapor';
insert into public.recipe_steps(dish_id,step_number,body) select id,3,'Apoya el recipiente sobre un soporte, sin sumergirlo en el agua. Tapa y cocina al vapor unos 30 minutos desde el hervor, hasta cocinar pollo y papas.' from public.dishes where slug='pollo-con-verduras-al-vapor';
insert into public.recipe_steps(dish_id,step_number,body) select id,4,'Añade holantao, frejol chino y cebolla china. Cocina al vapor 2 minutos más.' from public.dishes where slug='pollo-con-verduras-al-vapor';
insert into public.recipe_steps(dish_id,step_number,body) select id,5,'Salsa: combina cebolla roja, ají limo, rocoto, kion, ajo, sal y pimienta picados. Vierte cuidadosamente aceite caliente encima; añade aceite de ajonjolí y cebolla china. Sirve aparte.' from public.dishes where slug='pollo-con-verduras-al-vapor';
