insert into public.recipe_steps(dish_id,step_number,body) select id,1,'Chimichurri: pica ajo, culantro, huacatay y perejil. Mezcla con sal, pimienta y aceite; refrigera.' from public.dishes where slug='lechon-al-horno';
insert into public.recipe_steps(dish_id,step_number,body) select id,2,'Sumerge el lechón en salmuera refrigerada 2 horas, usando 100 g de sal por litro de agua. Escurre y acomódalo abierto para el horno; sazona con sal gruesa.' from public.dishes where slug='lechon-al-horno';
insert into public.recipe_steps(dish_id,step_number,body) select id,3,'Ponlo sobre una rejilla en una bandeja con papas cóctel, camote en cuartos y ajo. Sazona los tubérculos con sal, aceite de oliva y romero.' from public.dishes where slug='lechon-al-horno';
insert into public.recipe_steps(dish_id,step_number,body) select id,4,'Hornea a 180 °C unos 45 minutos. Retira y reserva los tubérculos cuando estén cocidos.' from public.dishes where slug='lechon-al-horno';
insert into public.recipe_steps(dish_id,step_number,body) select id,5,'Baña el lechón con su grasa y termina a 220 °C unas 2 horas, hasta cocinarlo y dejar la piel crocante.' from public.dishes where slug='lechon-al-horno';
insert into public.recipe_steps(dish_id,step_number,body) select id,6,'Corta en porciones y sirve con los tubérculos y el chimichurri. La cocción de un lechón entero requiere comprobar el punto según su tamaño.' from public.dishes where slug='lechon-al-horno';
