insert into public.recipe_steps(dish_id,step_number,body) select id,1,'Salsa de cocona: pela y corta la cocona con sus semillas. Mezcla con ají charapita picado, sachaculantro o culantro, cebolla, sal, pimienta y limón.' from public.dishes where slug='patacones-con-salsas';
