insert into public.recipe_steps(dish_id,step_number,body) select id,1,'Prepara el arroz graneado el día anterior y refrigéralo. Corta la pechuga en cubos y sazona con sal, pimienta y un poco de aceite.' from public.dishes where slug='arroz-chaufa-de-pollo';
insert into public.recipe_steps(dish_id,step_number,body) select id,2,'En un wok caliente, saltea el pollo hasta cocinarlo. Retíralo y reserva.' from public.dishes where slug='arroz-chaufa-de-pollo';
insert into public.recipe_steps(dish_id,step_number,body) select id,3,'En el wok con aceite, dora el kion unos segundos. Añade huevo batido; deja cuajar y rompe la tortilla.' from public.dishes where slug='arroz-chaufa-de-pollo';
insert into public.recipe_steps(dish_id,step_number,body) select id,4,'Incorpora el arroz frío y suelta los granos. Devuelve el pollo y añade azúcar y sillao; saltea a fuego alto.' from public.dishes where slug='arroz-chaufa-de-pollo';
insert into public.recipe_steps(dish_id,step_number,body) select id,5,'Añade frejol chino si lo elegiste y cebolla china. Retira del fuego, incorpora unas gotas de aceite de ajonjolí y sirve.' from public.dishes where slug='arroz-chaufa-de-pollo';
