insert into public.recipe_steps(dish_id,step_number,body) select id,1,'Prepara y refrigera el arroz graneado la víspera. Limpia los mariscos, corta el calamar en aros y reserva las carcasas para el caldo.' from public.dishes where slug='arroz-con-mariscos';
insert into public.recipe_steps(dish_id,step_number,body) select id,2,'Cuece choclo y arvejas aparte. Hierve el pulpo con cebolla, ajo, tomate y laurel 20–30 minutos, hasta ablandarlo; enfría y corta.' from public.dishes where slug='arroz-con-mariscos';
insert into public.recipe_steps(dish_id,step_number,body) select id,3,'Caldo: sofríe cebolla, apio, ajo y tomate 3 minutos; añade panca y cocina 5. Incorpora carcasas, cangrejos, choros, perejil, culantro y agua; hierve 20 minutos. Cuela; reserva los choros.' from public.dishes where slug='arroz-con-mariscos';
insert into public.recipe_steps(dish_id,step_number,body) select id,4,'Saltea langostinos, calamar y pulpo brevemente a fuego alto; reserva.' from public.dishes where slug='arroz-con-mariscos';
insert into public.recipe_steps(dish_id,step_number,body) select id,5,'Sofríe cebolla, ajo, pimienta y comino 5 minutos. Añade ají panca y amarillo; cocina otros 5.' from public.dishes where slug='arroz-con-mariscos';
insert into public.recipe_steps(dish_id,step_number,body) select id,6,'Incorpora culantro, ají amarillo y pimiento en tiras. Vierte cerveza y deja evaporar el alcohol.' from public.dishes where slug='arroz-con-mariscos';
insert into public.recipe_steps(dish_id,step_number,body) select id,7,'Añade caldo y sal, luego arroz cocido, mariscos salteados, arvejas, choclo y choros. Integra sin recocer los mariscos.' from public.dishes where slug='arroz-con-mariscos';
insert into public.recipe_steps(dish_id,step_number,body) select id,8,'Ajusta limón y sal; termina con culantro y sirve.' from public.dishes where slug='arroz-con-mariscos';
