insert into public.recipe_steps(dish_id,step_number,body) select id,1,'Deshuesa la pechuga, retira la piel y separa los filetes. Aplánalos protegidos con film o papel manteca.' from public.dishes where slug='pollo-a-la-cordon-bleu-con-salsa-bechamel';
insert into public.recipe_steps(dish_id,step_number,body) select id,2,'Coloca queso paria y jamón sobre cada filete. Enrolla apretando, ata con hilo de cocina y salpimienta.' from public.dishes where slug='pollo-a-la-cordon-bleu-con-salsa-bechamel';
insert into public.recipe_steps(dish_id,step_number,body) select id,3,'Pasa cada rollo por harina, huevo batido y pan rallado; sacude el sobrante de harina.' from public.dishes where slug='pollo-a-la-cordon-bleu-con-salsa-bechamel';
