insert into public.recipe_steps(dish_id,step_number,body) select id,1,'Salpimienta la carne en trozos y séllala por todos sus lados en una olla con aceite. Reserva.' from public.dishes where slug='estofado-de-carne';
insert into public.recipe_steps(dish_id,step_number,body) select id,2,'En esa olla sofríe cebolla 5 minutos, ajo 3 y pasta de tomate otros 3. Añade tomate pelado picado y cocina 5 minutos.' from public.dishes where slug='estofado-de-carne';
insert into public.recipe_steps(dish_id,step_number,body) select id,3,'Vierte vino y deja evaporar el alcohol. Devuelve la carne, añade agua o caldo y cocina tapado a fuego medio una hora, revisando el líquido cada 20 minutos.' from public.dishes where slug='estofado-de-carne';
insert into public.recipe_steps(dish_id,step_number,body) select id,4,'Incorpora laurel y pasas si las elegiste; cocina otra hora, hasta ablandar la carne.' from public.dishes where slug='estofado-de-carne';
insert into public.recipe_steps(dish_id,step_number,body) select id,5,'Agrega zanahoria en rodajas y cocina 5 minutos. Añade papa en cuartos y arvejas; cocina al menos 7 minutos, hasta que estén tiernas. Repón líquido si hace falta.' from public.dishes where slug='estofado-de-carne';
insert into public.recipe_steps(dish_id,step_number,body) select id,6,'Ajusta la sal y añade perejil o culantro. Sirve con arroz blanco cocido aparte.' from public.dishes where slug='estofado-de-carne';
