insert into public.recipe_steps(dish_id,step_number,body) select id,1,'Limpia cabezas, espinazos de pescado y choros. Hiérvelos con cebolla, apio, ajo, kion, culantro y ají limo.' from public.dishes where slug='chilcano-de-pescado';
insert into public.recipe_steps(dish_id,step_number,body) select id,2,'Retira la espuma a los 2 minutos y continúa a hervor suave unos 30–40 minutos. Cuela y sazona el caldo.' from public.dishes where slug='chilcano-de-pescado';
insert into public.recipe_steps(dish_id,step_number,body) select id,3,'Aparte, mezcla pescado fresco en cubos con sal, ají limo, culantro y limón. Añade choclo cocido y cancha.' from public.dishes where slug='chilcano-de-pescado';
insert into public.recipe_steps(dish_id,step_number,body) select id,4,'Coloca una pequeña porción de ese cebiche en cada taza, agrega yuyo y vierte el caldo colado caliente.' from public.dishes where slug='chilcano-de-pescado';
insert into public.recipe_steps(dish_id,step_number,body) select id,5,'Termina con cebolla china y cancha. El pescado fresco del acompañamiento es distinto de las cabezas usadas para el caldo.' from public.dishes where slug='chilcano-de-pescado';
