insert into public.recipe_steps(dish_id,step_number,body) select id,1,'Lava la quinua hasta que el agua salga clara. Cocínala con el doble de agua; al hervir, tapa y baja el fuego 20 minutos. Deja enfriar.' from public.dishes where slug='ensalada-cremosa-de-quinua';
insert into public.recipe_steps(dish_id,step_number,body) select id,2,'Hierve brócoli, arvejas y vainitas 4 minutos. Añade espinaca y cocina 2 más; enfría en agua helada y escurre. Corta la espinaca.' from public.dishes where slug='ensalada-cremosa-de-quinua';
insert into public.recipe_steps(dish_id,step_number,body) select id,3,'Aliño: licúa parte de la palta con culantro, yogur, ajo, limón, sal, pimienta, orégano, líquido de la conserva de atún, aceite de oliva y agua hervida fría.' from public.dishes where slug='ensalada-cremosa-de-quinua';
insert into public.recipe_steps(dish_id,step_number,body) select id,4,'Mezcla quinua y verduras con pepino, atún escurrido, pimiento y la palta restante en cubos.' from public.dishes where slug='ensalada-cremosa-de-quinua';
insert into public.recipe_steps(dish_id,step_number,body) select id,5,'Sirve con huevo cocido y el aliño cremoso al gusto.' from public.dishes where slug='ensalada-cremosa-de-quinua';
