insert into public.recipe_steps(dish_id,step_number,body) select id,1,'Hierve los huesos de pollo en agua unos 25 minutos. Cuela y reserva el caldo.' from public.dishes where slug='aguadito-de-pollo';
insert into public.recipe_steps(dish_id,step_number,body) select id,2,'Sofríe cebolla con aceite 5 minutos. Añade ajo, sal y pimienta; cocina 3 minutos. Incorpora ají amarillo y cocina 5, luego culantro licuado y cocina otros 3.' from public.dishes where slug='aguadito-de-pollo';
insert into public.recipe_steps(dish_id,step_number,body) select id,3,'Vierte el caldo y añade kion. Cuando hierva, incorpora menudencias, alas, pescuezos y arroz crudo; cocina 10 minutos.' from public.dishes where slug='aguadito-de-pollo';
