insert into public.recipe_steps(dish_id,step_number,body) select id,1,'Cubre el cerdo con salmuera de 5 cucharadas de sal por litro de agua y refrigera al menos 4 horas. Enjuaga, seca y marca superficialmente la piel.' from public.dishes where slug='lomito-de-cerdo-al-horno';
insert into public.recipe_steps(dish_id,step_number,body) select id,2,'Hornea a 230 °C 45 minutos. Añade poro, apio, zanahoria, romero, ajo y vino; hornea otros 15 minutos.' from public.dishes where slug='lomito-de-cerdo-al-horno';
insert into public.recipe_steps(dish_id,step_number,body) select id,3,'Cubre con aluminio; hornea a 160 °C unas 2 horas, hasta ablandar. Destapa y dora a 230 °C aproximadamente una hora; repón agua si se secan las verduras.' from public.dishes where slug='lomito-de-cerdo-al-horno';
insert into public.recipe_steps(dish_id,step_number,body) select id,4,'Retira el cerdo, separa la grasa de sus jugos y cuela el líquido.' from public.dishes where slug='lomito-de-cerdo-al-horno';
insert into public.recipe_steps(dish_id,step_number,body) select id,5,'Salsa oriental: calienta azúcar, hoisin, salsa de ostión, kion y canela china a fuego bajo 5 minutos. Añade jugos del cerdo y reduce hasta espesar.' from public.dishes where slug='lomito-de-cerdo-al-horno';
insert into public.recipe_steps(dish_id,step_number,body) select id,6,'Incorpora guindones y pasas hidratadas. Corta el cerdo y sirve con la salsa caliente.' from public.dishes where slug='lomito-de-cerdo-al-horno';
insert into public.recipe_steps(dish_id,step_number,body) select id,7,'Los tiempos de horno corresponden a la pieza de la fuente; comprueba la cocción cuando cambie su tamaño.' from public.dishes where slug='lomito-de-cerdo-al-horno';
