insert into public.recipe_steps(dish_id,step_number,body) select id,1,'Boloñesa: sofríe cebolla con aceite 5 minutos. Incorpora apio, ajo, romero y zanahoria picados, dejando cocinar cada incorporación.' from public.dishes where slug='lasana-a-la-bolonesa';
insert into public.recipe_steps(dish_id,step_number,body) select id,2,'Añade las carnes molidas de res y cerdo; cocina hasta que dejen de soltar líquido y comiencen a dorarse.' from public.dishes where slug='lasana-a-la-bolonesa';
insert into public.recipe_steps(dish_id,step_number,body) select id,3,'Añade tomate licuado sin piel ni pepas, azúcar, vino y laurel. Evapora el alcohol; cubre con agua o caldo y cocina tapado al menos 45 minutos. Sazona.' from public.dishes where slug='lasana-a-la-bolonesa';
insert into public.recipe_steps(dish_id,step_number,body) select id,4,'Salsa blanca: derrite mantequilla y bate con harina a fuego medio bajo 4–5 minutos. Añade leche caliente batiendo; espesa y sazona con nuez moscada, sal y pimienta.' from public.dishes where slug='lasana-a-la-bolonesa';
insert into public.recipe_steps(dish_id,step_number,body) select id,5,'Prepara las láminas de lasaña según su empaque. Alterna boloñesa, salsa blanca, mozzarella y pasta; termina con salsa blanca.' from public.dishes where slug='lasana-a-la-bolonesa';
insert into public.recipe_steps(dish_id,step_number,body) select id,6,'Cubre con aluminio y hornea a 180 °C 25 minutos. Destapa, añade parmesano y gratina a 200 °C unos 15 minutos.' from public.dishes where slug='lasana-a-la-bolonesa';
insert into public.recipe_steps(dish_id,step_number,body) select id,7,'Deja reposar unos minutos antes de cortar.' from public.dishes where slug='lasana-a-la-bolonesa';
