insert into public.recipe_steps(dish_id,step_number,body) select id,1,'Salpimienta la pieza de res con comino. Séllala por todos sus lados en una olla con aceite; reserva.' from public.dishes where slug='asado-de-res-con-pure';
insert into public.recipe_steps(dish_id,step_number,body) select id,2,'Sofríe cebolla 10 minutos en esa olla, ajo 5, tomate pelado 10 y pasta de tomate otros 5.' from public.dishes where slug='asado-de-res-con-pure';
insert into public.recipe_steps(dish_id,step_number,body) select id,3,'Añade zanahoria, devuelve la carne y vierte vino. Incorpora laurel y cocina destapado hasta evaporar el alcohol.' from public.dishes where slug='asado-de-res-con-pure';
insert into public.recipe_steps(dish_id,step_number,body) select id,4,'Cubre con agua caliente y cocina tapado a fuego medio 90 minutos. Voltea la carne y continúa destapado una hora, hasta ablandarla.' from public.dishes where slug='asado-de-res-con-pure';
insert into public.recipe_steps(dish_id,step_number,body) select id,5,'Retira y corta el asado en láminas. Licúa sus jugos con las verduras y redúcelos en la olla hasta formar una salsa; ajusta sal y pimienta.' from public.dishes where slug='asado-de-res-con-pure';
insert into public.recipe_steps(dish_id,step_number,body) select id,6,'Devuelve la carne a esa salsa, deja hervir y mantén caliente.' from public.dishes where slug='asado-de-res-con-pure';
insert into public.recipe_steps(dish_id,step_number,body) select id,7,'Puré: sancocha, pela y prensa las papas. Calienta mantequilla, incorpora la papa y leche tibia; bate hasta obtener un puré cremoso y ajusta la sal.' from public.dishes where slug='asado-de-res-con-pure';
insert into public.recipe_steps(dish_id,step_number,body) select id,8,'Sirve el asado y su salsa junto al puré.' from public.dishes where slug='asado-de-res-con-pure';
