insert into public.recipe_steps(dish_id,step_number,body) select id,1,'Wantanes: mezcla cerdo, 1/2 cucharadita de kion, ajo, cebolla china, sillao, 1 cucharada de fécula, huevo, sal, pimienta y 1 cucharada de aceite de ajonjolí.' from public.dishes where slug='kam-lu-wantan';
insert into public.recipe_steps(dish_id,step_number,body) select id,2,'Rellena las pastas, pliega y sella con huevo batido. Fríe a fuego medio hasta cocinar el relleno; escurre.' from public.dishes where slug='kam-lu-wantan';
insert into public.recipe_steps(dish_id,step_number,body) select id,3,'Granea arroz aparte. Diluye tamarindo en agua hirviendo.' from public.dishes where slug='kam-lu-wantan';
insert into public.recipe_steps(dish_id,step_number,body) select id,4,'Salsa: sofríe kion restante y kétchup 2 minutos. Añade azúcar, tamarindo y poca agua; hierve.' from public.dishes where slug='kam-lu-wantan';
insert into public.recipe_steps(dish_id,step_number,body) select id,5,'Agrega pollo en láminas, champiñones y holantao; cocina a fuego medio hasta cocinar el pollo.' from public.dishes where slug='kam-lu-wantan';
insert into public.recipe_steps(dish_id,step_number,body) select id,6,'Añade aceite de ajonjolí restante, durazno y piña. Espesa gradualmente con fécula restante disuelta en agua fría.' from public.dishes where slug='kam-lu-wantan';
