insert into public.recipe_steps(dish_id,step_number,body) select id,1,'Hidrata el chinguirito en agua caliente al menos 30 minutos, hasta ablandarlo.' from public.dishes where slug='torrejitas-de-choclo-con-bonito-y-chinguirito';
