insert into public.recipe_steps(dish_id,step_number,body) select id,1,'Corta las presas para facilitar la cocción. Cúbrelas con leche y sal; refrigera toda la noche.' from public.dishes where slug='pollo-broaster';
insert into public.recipe_steps(dish_id,step_number,body) select id,2,'Mezcla harina, sal, pimienta, orégano, páprika, ajo en polvo y comino; añade cayena si la elegiste. Bate huevos con sillao en otro recipiente.' from public.dishes where slug='pollo-broaster';
insert into public.recipe_steps(dish_id,step_number,body) select id,3,'Escurre y seca el pollo. Pásalo por huevo, harina, huevo y harina otra vez; sacude el sobrante.' from public.dishes where slug='pollo-broaster';
