insert into public.recipe_steps(dish_id,step_number,body) select id,1,'Remoja los garbanzos toda la noche. Escurre y hiérvelos en una olla aparte sin sal, hasta ablandarlos.' from public.dishes where slug='sancochado-limeno';
insert into public.recipe_steps(dish_id,step_number,body) select id,2,'Hierve la carne 30 minutos, retirando espuma. Añade poro, zanahoria, nabo y apio; cocina a hervor moderado unas 2 horas, hasta ablandar.' from public.dishes where slug='sancochado-limeno';
insert into public.recipe_steps(dish_id,step_number,body) select id,3,'Retira y reserva zanahoria y nabo. Incorpora papa y yuca y retíralas al ablandar, sin dejarlas deshacer.' from public.dishes where slug='sancochado-limeno';
insert into public.recipe_steps(dish_id,step_number,body) select id,4,'Cuece después choclo y col en el mismo caldo y reserva cuando estén listos.' from public.dishes where slug='sancochado-limeno';
insert into public.recipe_steps(dish_id,step_number,body) select id,5,'Retira la carne y cuela el caldo, descartando apio y poro. Ajusta la sal.' from public.dishes where slug='sancochado-limeno';
