insert into public.recipe_steps(dish_id,step_number,body) select id,1,'Marina el cabrito con chicha, ajo, culantro, sal y pimienta toda la noche en refrigeración. Remoja los frejoles aparte.' from public.dishes where slug='seco-de-cabrito-a-la-nortena';
