insert into public.recipe_steps(dish_id,step_number,body) select id,1,'Hierve huesos limpios de pato en agua unos 30 minutos. Cuela y reserva el caldo.' from public.dishes where slug='arroz-con-pato-a-la-chiclayana';
insert into public.recipe_steps(dish_id,step_number,body) select id,2,'Dora las presas salpimentadas por ambos lados, empezando por la piel. Retíralas y elimina el exceso de grasa de la olla.' from public.dishes where slug='arroz-con-pato-a-la-chiclayana';
