insert into public.recipe_steps(dish_id,step_number,body) select id,5,'Retira las presas cocidas. Agrega arroz crudo, arvejas y loche en cubos al caldo; comprueba la cantidad de líquido para granear el arroz.' from public.dishes where slug='arroz-con-pato-a-la-chiclayana';
insert into public.recipe_steps(dish_id,step_number,body) select id,6,'Cuando hierva, tapa y cocina a fuego mínimo unos 20 minutos. Devuelve el pato para calentarlo y sirve con sarsa criolla.' from public.dishes where slug='arroz-con-pato-a-la-chiclayana';
