insert into public.recipe_steps(dish_id,step_number,body) select id,1,'Corta pollo en tiras y cebolla y ají amarillo en juliana. Mezcla ajo, panca, vinagre, sal, pimienta, comino, orégano y limón; marina el pollo en refrigeración al menos 2 horas.' from public.dishes where slug='wraps-de-pollo-anticuchero';
