insert into public.recipe_steps(dish_id,step_number,body) select id,3,'Saltea el pollo marinado con aceite en un wok caliente unos 4 minutos, hasta cocinarlo. Añade cebolla y ají amarillo y saltea brevemente.' from public.dishes where slug='wraps-de-pollo-anticuchero';
insert into public.recipe_steps(dish_id,step_number,body) select id,4,'Calienta las tortillas en una sartén unos 30 segundos por lado.' from public.dishes where slug='wraps-de-pollo-anticuchero';
