values ('tarwi','Tarwi','Menestra','Frío','menestra','frio','imagenes-platos/webp/tarwi.webp',true,'{"slug":"tarwi","winnerId":"old:tarwi","groupId":"group:old:tarwi","n":"Tarwi","aliases":["Tarwi"],"active":true,"portions":2,"ingredients":[{"name":"Tarwi","recipe_name":"Tarwi","quantity":"350 g","shopping_quantity":"350 g","cooking_quantity":"","pantry":false,"optional":false,"inferred":true,"source":"revisión final","inferred_reason":"Cantidad editorial, no especificada por la fuente","category":"Verduras y otros"},{"name":"Carne Seca","recipe_name":"Carne Seca","quantity":"80 g","shopping_quantity":"80 g","cooking_quantity":"","pantry":false,"optional":false,"inferred":true,"source":"revisión final","inferred_reason":"Cantidad editorial, no especificada por la fuente","category":"Proteínas"},{"name":"Papa","recipe_name":"Papa","quantity":"250 g","shopping_quantity":"250 g","cooking_quantity":"","pantry":false,"optional":false,"inferred":true,"source":"revisión final","inferred_reason":"Cantidad editorial, no especificada por la fuente","category":"Verduras y otros"},{"name":"Cebolla","recipe_name":"Cebolla","quantity":"1 unid","shopping_quantity":"1 unid","cooking_quantity":"","pantry":false,"optional":false,"inferred":true,"source":"revisión final","inferred_reason":"Cantidad editorial, no especificada por la fuente","category":"Verduras y otros"},{"name":"Tomate","recipe_name":"Tomate","quantity":"1 unid","shopping_quantity":"1 unid","cooking_quantity":"","pantry":false,"optional":false,"inferred":true,"source":"revisión final","inferred_reason":"Cantidad editorial, no especificada por la fuente","category":"Verduras y otros"},{"name":"Ajo","recipe_name":"Ajo","quantity":"2 dientes","shopping_quantity":"2 dientes","cooking_quantity":"","pantry":false,"optional":false,"inferred":true,"source":"revisión final","inferred_reason":"Cantidad editorial, no especificada por la fuente","category":"Verduras y otros"},{"name":"Pasta de Ají Panca","recipe_name":"Pasta de Ají Panca","quantity":"1 cda","shopping_quantity":"1 cda","cooking_quantity":"","pantry":false,"optional":false,"inferred":true,"source":"revisión final","inferred_reason":"Cantidad editorial, no especificada por la fuente","category":"Verduras y otros"},{"name":"Pimentón","recipe_name":"Pimentón","quantity":"1 cdta","shopping_quantity":"1 cdta","cooking_quantity":"","pantry":false,"optional":false,"inferred":true,"source":"revisión final","inferred_reason":"Cantidad editorial, no especificada por la fuente","category":"Verduras y otros"},{"name":"Arroz","recipe_name":"Arroz","quantity":"180 g","shopping_quantity":"180 g","cooking_quantity":"","pantry":false,"optional":false,"inferred":true,"source":"revisión final","inferred_reason":"Cantidad editorial, no especificada por la fuente","category":"Abarrotes"}],"steps":["Usa tarwi cocido y desamargado. Pela y licúa con un poco de agua hasta formar una crema.","Remoja la carne seca, enjuaga y corta. Sancocha las papas, pela y aplasta.","Sofríe cebolla y ajo; agrega tomate picado, ají panca y pimentón. Cocina el aderezo.","Añade la carne y agua para guisarla hasta que esté tierna. Incorpora tarwi molido y papa aplastada.","Cocina removiendo hasta integrar y espesar; ajusta agua y sal. Sirve con arroz preparado aparte."],"provenance":{"winnerId":"old:tarwi","groupId":"group:old:tarwi","reviewed":true,"source":"INIA: El Tarwi, alternativa para la lucha contra la desnutrición infantil, puré tradicional, p. 39 impresa","url":"https://repositorio.inia.gob.pe/server/api/core/bitstreams/2f41e31a-c636-4432-9d1e-7a743c601dda/content","basePortions":2,"sourcePortions":null,"adaptation":"Preparación tradicional con papa y carne seca, no ensalada. La descripción de INIA no fija cantidades: estas cantidades para dos son editoriales y se identifican como estimadas. Comprar tarwi ya desamargado y cocido; no usar grano crudo sin desamargar."},"sourceUrl":"https://repositorio.inia.gob.pe/server/api/core/bitstreams/2f41e31a-c636-4432-9d1e-7a743c601dda/content","img":"imagenes-platos/generadas/tarwi.png","imageDecision":"keep_local","imageStatus":"kept","quick":false,"base":"Menestra","prep":"Frío","p":"frio","cat":"menestra"}'::jsonb,'2026-10-07')
