values ('locro-de-pecho','Locro de pecho','Res','Guiso','res','guiso','imagenes-platos/webp/locro-de-pecho.webp',true,'{"slug":"locro-de-pecho","winnerId":"old:locro-de-pecho","groupId":"group:old:locro-de-pecho","n":"Locro de pecho","aliases":["Locro de pecho"],"active":true,"portions":2,"ingredients":[{"name":"Carne de Res","recipe_name":"Carne de Res","quantity":"200 g","shopping_quantity":"200 g","cooking_quantity":"","pantry":false,"optional":false,"inferred":false,"source":"revisión final","inferred_reason":"","category":"Proteínas"},{"name":"Papa","recipe_name":"Papa","quantity":"250 g","shopping_quantity":"250 g","cooking_quantity":"","pantry":false,"optional":false,"inferred":false,"source":"revisión final","inferred_reason":"","category":"Verduras y otros"},{"name":"Cebolla","recipe_name":"Cebolla","quantity":"1/2 unid","shopping_quantity":"1/2 unid","cooking_quantity":"","pantry":false,"optional":false,"inferred":false,"source":"revisión final","inferred_reason":"","category":"Verduras y otros"},{"name":"Ajo","recipe_name":"Ajo","quantity":"3/4 cdta","shopping_quantity":"3/4 cdta","cooking_quantity":"","pantry":false,"optional":false,"inferred":false,"source":"revisión final","inferred_reason":"","category":"Verduras y otros"},{"name":"Pasta de Ají Panca","recipe_name":"Pasta de Ají Panca","quantity":"1/2 cda","shopping_quantity":"1/2 cda","cooking_quantity":"","pantry":false,"optional":false,"inferred":false,"source":"revisión final","inferred_reason":"","category":"Verduras y otros"},{"name":"Hierbabuena","recipe_name":"Hierbabuena","quantity":"al gusto","shopping_quantity":"al gusto","cooking_quantity":"","pantry":false,"optional":false,"inferred":false,"source":"revisión final","inferred_reason":"","category":"Verduras y otros"},{"name":"Perejil","recipe_name":"Perejil","quantity":"al gusto","shopping_quantity":"al gusto","cooking_quantity":"","pantry":false,"optional":false,"inferred":false,"source":"revisión final","inferred_reason":"","category":"V