values ('milanesa-de-pollo','Milanesa de pollo','Pollo','Frito','pollo','frito','imagenes-platos/webp/milanesa-de-pollo.webp',true,'{"slug":"milanesa-de-pollo","winnerId":"old:milanesa-de-pollo","groupId":"group:old:milanesa-de-pollo","n":"Milanesa de pollo","aliases":["Milanesa de pollo","Milanesa de Pollo"],"active":true,"portions":2,"ingredients":[{"name":"Pechuga de Pollo","quantity":"400 g","shopping_quantity":"400 g","cooking_quantity":"400 g","display":"Pechuga de pollo - 2 presas","source":"","original_quantity":"","portion_scaled":false,"pantry":false,"optional":false,"optional_reason":"","inferred":true,"inferred_reason":"Corrección editorial: pechuga por peso para dos porciones","category":"Proteínas"},{"name":"Pan Rallado","quantity":"1 taza","shopping_quantity":"1 taza","cooking_quantity":"","display":"Pan rallado - 1 taza","source":"","original_quantity":"","portion_scaled":false,"pantry":false,"optional":false,"optional_reason":"","inferred":false,"inferred_reason":"","category":"Abarrotes"},{"name":"Huevo","quantity":"2 unid","shopping_quantity":"2 unid","cooking_quantity":"","display":"Huevo - 2 unid","source":"","original_quantity":"","portion_scaled":false,"pantry":false,"optional":false,"optional_reason":"","inferred":false,"inferred_reason":"","category":"Lácteos y huevos"},{"name":"Papa","quantity":"3 unid","shopping_quantity":"3 unid","cooking_quantity":"","display":"Papa - 3 unid","source":"","original_quantity":"","portion_scaled":false,"pantry":false,"optional":false,"optional_reason":"","inferred":false,"inferred_reason":"","category":"Verduras y otros"},{"name":"Arroz","quantity":"0.35 kg","shopping_quantity":"0.35 kg","cooking_quantity":"aprox. 2 tazas","display":"Arroz - 0.35 kg","source":"","original_quantity":"","portion_scaled":false,"pantry":false,"optional":false,"optional_reason":"","inferred":false,"inferred_reason":"","category":"Abarrotes"},{"name":"Aceite","quantity":"cantidad necesaria","shopping_quantity":"cantidad necesaria