values ('tallarines-a-la-bolonesa','Tallarines a la boloñesa','Res','Pasta','res','pasta','imagenes-platos/webp/tallarines-a-la-bolonesa.webp',true,'{"slug":"tallarines-a-la-bolonesa","winnerId":"old:tallarines-a-la-bolonesa","groupId":"group:old:tallarines-a-la-bolonesa","n":"Tallarines a la boloñesa","aliases":["Tallarines a la boloñesa"],"active":true,"portions":2,"ingredients":[{"name":"Tallarín","quantity":"1 paquete","shopping_quantity":"1 paquete","cooking_quantity":"","display":"Tallarín - 1 paquete","source":"","original_quantity":"","portion_scaled":false,"pantry":false,"optional":false,"optional_reason":"","inferred":false,"inferred_reason":"","category":"Abarrotes"},{"name":"Carne Molida","quantity":"0.35 kg","shopping_quantity":"0.35 kg","cooking_quantity":"","display":"Carne molida - 0.35 kg","source":"","original_quantity":"","portion_scaled":false,"pantry":false,"optional":false,"optional_reason":"","inferred":false,"inferred_reason":"","category":"Proteínas"},{"name":"Tomate","quantity":"3 unid","shopping_quantity":"3 unid","cooking_quantity":"","display":"Tomate - 3 unid","source":"","original_quantity":"","portion_scaled":false,"pantry":false,"optional":false,"optional_reason":"","inferred":false,"inferred_reason":"","category":"Verduras y otros"},{"name":"Cebolla","quantity":"1 unid","shopping_quantity":"1 unid","cooking_quantity":"","display":"Cebolla roja - 1 unid","source":"","original_quantity":"","portion_scaled":false,"pantry":false,"optional":false,"optional_reason":"","inferred":false,"inferred_reason":"","category":"Verduras y otros"},{"name":"Aceite","quantity":"cantidad necesaria","shopping_quantity":"cantidad necesaria","cooking_quantity":"","display":"aceite - cantidad necesaria","source":"","original_quantity":"","portion_scaled":false,"pantry":true,"optional":false,"optional_reason":"","inferred":false,"inferred_reason":"","category":"Verduras y otros"},{"name":"Sal","quantity":"cantidad necesaria","shopping_quantity":"cantidad nec